/**
 * selectbox의 옵션을 만들어주는 함수
 * ver: 0  - 이번달 부터 2011년10월/2011년11월/2011년12월 식으로 12달 표시
 * ver: 1  - 월만 표시 1월/2월/3월
 *
 */
/**
 * @method
 * @name mkSboxOpt
 * @description desc
 * @param {string} ver desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.mkSboxOpt = function(ver) {
    var date = new Date();
    var year;
    var month;
    date.setMonth(date.getMonth(), 1);
    document.write("<option value='00'>--- 선택 ---</option>");
    for (var i = 1; i < 13; i++) {
        if (ver == 0) {
            year = date.getFullYear();
            month = (date.getMonth() + 1) + "";
            if (month.length == 1) month = "0" + month;
            date.setMonth(date.getMonth() + 1);
            document.write("<option value='" + (year + "" + month) + "'>" + year + "년" + month + "월" + "</option>");
        } else {
            document.write("<option value='" + i + "'>" + i + "월" + "</option>");
        }
    }
};




/**
 * 업종을 찾는 팝업
 * 호출한 페이지에 returnInd(nodedata); 메소드 있어야함./JLDFIL501000.jsp
 * ver: 1  - 월만 표시 1월/2월/3월
 *
 */
w = '375';
h = '220';
l = screen.width / 2 - scwin.w / 2;
t = screen.height / 2 - scwin.h / 2;
indCodeWin = null;
/**
 * @method
 * @name fn_OpenIndCodeWin
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_OpenIndCodeWin = function() {
    scwin.w = '375';
    scwin.h = '220';
    scwin.l = screen.width / 2 - scwin.w / 2;
    scwin.t = screen.height / 2 - scwin.h / 2;
    if (scwin.indCodeWin != null) {
        if (!indCodeWin.closed) {
            indCodeWin.close();
        }
    }
    scwin.indCodeWin = window.open("/common/popup_indcode.jsp", "pop_ind", "left=" + scwin.l + ",top=" + scwin.t + ",width=" + scwin.w + ",height=" + scwin.h + ",scrollbars=no,resizable=no");
};


/**
