//기존에 사용하던거 그대로 쓰려니..순서가 개판... KBoY 
/**
 * @method
 * @name changePage
 * @description desc
 * @param {string} ver1 desc
 * @param {string} ver2 desc
 * @param {string} state desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.changePage = function(ver1, ver2, state) {
    var form = document.preListForm;
    if (form.page.getValue() == '00') {
        if (form.mode.getValue() == 'new') {
            alert("모든 메뉴는 '기업개요'작성 이후에 작성이 가능합니다.");
        } else {
            if (state == '' || state == '30' || state == '35' || state == '37') {
                if (confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\r\n이동하시겠습니까?')) scwin.doChangePage(ver1, ver2);
            } else scwin.doChangePage(ver1, ver2);
        }
    } else {
        if (state == '' || state == '30' || state == '35' || state == '37') {
            if (confirm('메뉴를 이동하면 저장 이후 수정된 내용은 반영되지 않습니다.\r\n이동하시겠습니까?')) scwin.doChangePage(ver1, ver2);
        } else scwin.doChangePage(ver1, ver2);
    }
};



//기존에 사용하던거 그대로 쓰려니..순서가 개판... KBoY 
/**
