//상장주선인 ID 기본정보를 갖고 있는 펑션(아이디배정에서 사용)
/**
 * @method
 * @name idInfo
 * @description desc
 * @param {string} integUsrId desc
 * @param {string} usrNm desc
 * @param {string} email desc
 * @param {string} telNo desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.idInfo = function(integUsrId, usrNm, email, telNo) {
    this.integ_usr_id = integUsrId;
    this.usr_nm = usrNm;
    this.email = email;
    this.tel_no = telNo;
};
